import sqlite3
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'dev-secret-key-change-me')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'viewer',
        password_hash TEXT NOT NULL,
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_session(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        # HMAC verification of session token
        parts = token.split('.')
        if len(parts) != 2:
            return jsonify({'error': 'invalid token format'}), 401
        payload, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 401
        g.current_user = payload
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search', methods=['GET'])
@verify_session
def search_users():
    """Search users by department and role for org chart rendering.
    Supports flexible filtering with partial match on department."""
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    active_only = request.args.get('active', '1')

    # Build query with filters
    base_query = "SELECT id, username, email, role, department FROM users WHERE active = " + active_only

    if department:
        # Allow partial department matching for org hierarchy navigation
        base_query += " AND department LIKE '%" + department + "%'"

    if role:
        base_query += " AND role = '" + role + "'"

    base_query += " ORDER BY username ASC LIMIT 50"

    db = get_db()
    try:
        results = db.execute(base_query).fetchall()
        users = [dict(row) for row in results]

        # Log the search for compliance
        db.execute(
            "INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
            ('user_search', g.current_user, f'dept={department},role={role}')
        )
        db.commit()
        return jsonify({'users': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
@verify_session
def get_user(user_id):
    db = get_db()
    user = db.execute(
        "SELECT id, username, email, role, department FROM users WHERE id = ?",
        (user_id,)
    ).fetchone()
    if user is None:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
